//go:build !codegen
// +build !codegen

// The public parity report: the published page that makes the parity claim
// verifiable instead of trusted. It renders exclusively from the accounting
// and the measurement report -- never hand-authored numbers -- and it is a
// COMMITTED, drift-tested artifact: the generated bytes live at
// catalog/<provider>/terraform-parity.md (beside the generated
// reference-index.md, the same committed-generated-markdown grain), the
// drift test fails CI whenever the committed page and a fresh render
// diverge, and the site build carries the page onto the public docs site.
//
// Two honesty rules are load-bearing here:
//
//   - The page never claims achieved parity. It shows the measured state --
//     accounting per kind, dispositions per resource, live-proof status per
//     kind -- against the named pin. Claim language stays "built for 100%
//     Terraform parity" until every kind is accounted AND proven.
//   - PROVEN comes only from the E2E profiles (the tree's record of live
//     dual-engine runs), joined mechanically in e2eproof.go. A kind is
//     proven when its profile is green with both provisioners validated.
//
// Each page embeds its own generation parameters (provider and GA schema)
// in the header comment, so the drift gate regenerates every committed page
// without per-provider configuration: enrollment is generating the page
// once with explicit flags, exactly like the manifests' file-presence rule.
package providerparity

import (
	"fmt"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"github.com/pkg/errors"
	"github.com/plantonhq/planton/pkg/crkreflect"
	"github.com/plantonhq/planton/shared/cloudresourcekind"
)

// PublicReportFileName is the page's file name under each provider's
// catalog directory.
const PublicReportFileName = "terraform-parity.md"

// PublicReportPath is the repo-root-relative committed location of one
// provider's parity report page.
func PublicReportPath(provider cloudresourcekind.CloudResourceProvider) string {
	return filepath.Join(catalogRoot, crkreflect.ProviderDirName(provider), PublicReportFileName)
}

// providerFromName resolves a provider name (the catalog directory name the
// pages embed, e.g. "gcp" or "digitalocean"; enum names are accepted too)
// to its enum value -- the drift gate uses it to turn a page's embedded
// parameters back into a generation input.
func providerFromName(name string) (cloudresourcekind.CloudResourceProvider, error) {
	provider := crkreflect.ProviderFromString(name)
	if provider == cloudresourcekind.CloudResourceProvider_cloud_resource_provider_unspecified {
		return 0, errors.Errorf("unknown cloud provider %q", name)
	}
	return provider, nil
}

// providerDisplayName renders a provider's user-facing name for the page
// heading from the registry's provider_meta (e.g. digitalocean ->
// "DigitalOcean"). A name outside the registry (hermetic test fixtures)
// falls back to upper-casing, the registry display names' own style for
// initialisms (GCP, AWS).
func providerDisplayName(name string) string {
	provider := crkreflect.ProviderFromString(name)
	if meta, err := crkreflect.ProviderMetaOf(provider); err == nil && meta.DisplayName != "" {
		return meta.DisplayName
	}
	return strings.ToUpper(name)
}

// reportParamsRe extracts the embedded generation parameters from a
// committed page. The line is machine-read by the drift gate; changing its
// shape is a breaking change for every committed page.
var reportParamsRe = regexp.MustCompile(`(?m)^     parameters: provider=([a-z0-9]+) ga-schema=([a-z0-9-]+)$`)

// ParseReportParams reads the provider and GA schema a committed page was
// generated with.
func ParseReportParams(page string) (providerName, gaSchema string, err error) {
	m := reportParamsRe.FindStringSubmatch(page)
	if m == nil {
		return "", "", errors.New("page carries no embedded generation parameters -- regenerate it with --write-report")
	}
	return m[1], m[2], nil
}

// GeneratePublicReport builds and renders one provider's parity page:
// measurement, accounting, and E2E proof joined into deterministic
// markdown. This is the ONE composition the CLI's --write-report and the
// drift gate both call, so the committed page and the check can never
// disagree.
func GeneratePublicReport(repoRoot string, provider cloudresourcekind.CloudResourceProvider, schemas map[string]*Schema, gaSchema, dispositionsPath, admissionsDir string) (string, error) {
	rep, err := BuildReport(repoRoot, provider, schemas)
	if err != nil {
		return "", err
	}
	acc, err := BuildAccounting(repoRoot, provider, schemas, gaSchema, dispositionsPath, admissionsDir)
	if err != nil {
		return "", err
	}
	proofs, err := BuildE2EProofs(repoRoot, provider)
	if err != nil {
		return "", err
	}
	return RenderPublicReport(rep, acc, proofs), nil
}

// RenderPublicReport renders the page from already-built inputs. Pure and
// deterministic: no timestamps (freshness is the named pin, and byte-stable
// output is what lets the drift gate freeze the artifact), every section
// sorted by its input's ordering.
func RenderPublicReport(rep Report, acc Accounting, proofs map[string]E2EProof) string {
	var b strings.Builder
	providerTitle := providerDisplayName(acc.CloudProvider)

	fmt.Fprintf(&b, `---
title: "Terraform Parity"
description: "Measured parity of the %s catalog against the pinned Terraform provider"
icon: "check-circle"
order: 90
---

<!-- GENERATED FILE -- DO NOT EDIT.
     Rendered from the committed provider schemas, the kind registry, the
     Terraform modules, the per-kind provider-parity manifests, the
     dispositions ledger, and the E2E profiles.
     parameters: provider=%s ga-schema=%s
     Regenerate: make generate-provider-parity-report -->

# %s Terraform Parity

This catalog is **built for 100%% Terraform parity**: every configurable
argument of the pinned Terraform provider is representable through a kind,
and every provider resource carries exactly one recorded disposition --
omission is a decision, never an accident. This page is the measurement,
generated from the same accounting that gates the repository's CI. It makes
no achieved-parity claim: a kind counts as PROVEN only when live end-to-end
runs pass on both IaC engines, and the tables below show exactly how far
that has progressed.

`, providerTitle, acc.CloudProvider, acc.GASchema, providerTitle)

	// Measurement baseline. The loaded schema set spans every provider the
	// repository measures, but each page lists only its own yardsticks: the
	// GA parity baseline plus any schema whose provider this catalog's
	// modules actually pin (a beta admission returns its schema to the
	// table through the pin, automatically). Unrelated providers' artifacts
	// never appear here. The baseline renders FIRST and every other pinned
	// schema is labeled for what it is -- a schema consulted only because
	// this catalog's modules pin that provider (helper data sources, or an
	// admitted secondary channel) -- so no reader mistakes a helper pin for
	// the yardstick parity is declared against.
	b.WriteString("## Measurement baseline\n\n")
	b.WriteString("| | |\n|---|---|\n")
	fmt.Fprintf(&b, "| Provider schema (parity baseline) | `%s@%s` |\n", acc.GASchema, rep.SchemaVersions[acc.GASchema])
	schemaNames := make([]string, 0, len(rep.SchemaVersions))
	for name := range rep.SchemaVersions {
		if name == acc.GASchema || len(rep.PinDistribution[name]) == 0 {
			continue
		}
		schemaNames = append(schemaNames, name)
	}
	sort.Strings(schemaNames)
	for _, name := range schemaNames {
		fmt.Fprintf(&b, "| Supporting schema (pinned by this catalog's modules) | `%s@%s` |\n", name, rep.SchemaVersions[name])
	}
	fmt.Fprintf(&b, "| Kinds in the catalog | %d |\n", rep.Kinds)
	fmt.Fprintf(&b, "| Distinct provider resources consumed | %d |\n", rep.DistinctResources)
	fmt.Fprintf(&b, "| Spec fields authored across all kinds | %d |\n", rep.TotalSpecFields)
	pinProviders := make([]string, 0, len(rep.PinDistribution))
	for name := range rep.PinDistribution {
		pinProviders = append(pinProviders, name)
	}
	sort.Strings(pinProviders)
	for _, name := range pinProviders {
		constraints := make([]string, 0, len(rep.PinDistribution[name]))
		for c := range rep.PinDistribution[name] {
			constraints = append(constraints, c)
		}
		sort.Strings(constraints)
		parts := make([]string, 0, len(constraints))
		for _, c := range constraints {
			parts = append(parts, fmt.Sprintf("`%s` × %d", c, rep.PinDistribution[name][c]))
		}
		fmt.Fprintf(&b, "| Module pins on `%s` | %s |\n", name, strings.Join(parts, ", "))
	}
	b.WriteString("\nThe GA provider is the parity baseline. Capability that exists only in a\n")
	b.WriteString("secondary channel (for Google, the `google-beta` provider) enters per kind\n")
	b.WriteString("through the admission list (`pkg/providerparity/admissions/`), never\n")
	b.WriteString("wholesale: one entry per resource per kind, with the reason and where its\n")
	b.WriteString("promotion to the baseline is tracked. The accounting reads the list -- an\n")
	b.WriteString("admitted resource is measured against its channel's schema, an unadmitted\n")
	b.WriteString("secondary-channel resource is a finding, and an admitted resource the\n")
	b.WriteString("baseline serves at the pin is a stale admission.\n\n")

	// The admission list, rendered only where one exists: a catalog with no
	// secondary channel says nothing here rather than printing an empty
	// table that reads as a claim.
	if len(acc.Admissions) > 0 {
		b.WriteString("## Secondary-channel admissions\n\n")
		b.WriteString("| Resource | Channel | Kind | Reason | Promotion tracked at |\n")
		b.WriteString("|---|---|---|---|---|\n")
		for _, a := range acc.Admissions {
			fmt.Fprintf(&b, "| `%s` | `%s` | %s | %s | %s |\n",
				a.Resource, a.Provider, a.Kind, a.Reason, a.PromotionTracking)
		}
		b.WriteString("\n")
	}

	// The provider block, when this provider is enrolled for it.
	if pc := acc.ProviderConfig; pc != nil {
		b.WriteString("## The provider block\n\n")
		b.WriteString("Parity covers the provider's own configuration block -- credentials,\n")
		b.WriteString("role-assumption chains, default tags, endpoint overrides, retry tuning --\n")
		b.WriteString("under the same total-accounting rule as resources: every configurable,\n")
		b.WriteString("non-deprecated provider-block argument is matched to a provider-config\n")
		b.WriteString("field, mapped by recorded judgment, owned by the modules by recorded\n")
		b.WriteString("judgment, or excluded with a recorded reason -- and arguments set inside\n")
		b.WriteString("catalog modules' own provider blocks must carry that judgment too.\n\n")
		gaps := len(pc.UnaccountedArgs) + len(pc.UncoveredConfigFields) + len(pc.UnjudgedModuleArgs) + len(pc.ManifestStale)
		accountedCell := "❌"
		if pc.Accounted() {
			accountedCell = "✅"
		}
		b.WriteString("| Provider-block args | Matched | Mapped | Module-owned | Excluded | Open gaps | Accounted |\n")
		b.WriteString("|---|---|---|---|---|---|---|\n")
		fmt.Fprintf(&b, "| %d | %d | %d | %d | %d | %d | %s |\n\n",
			pc.TotalArgs, pc.MatchedArgs, pc.MappedArgs, pc.ModuleOwnedArgs, pc.ExcludedArgs, gaps, accountedCell)
	}

	// Depth.
	accounted, proven := 0, 0
	for _, k := range acc.Kinds {
		if k.Accounted() {
			accounted++
		}
		if proofs[k.Kind].Proven() {
			proven++
		}
	}
	b.WriteString("## Depth: per-kind accounting\n\n")
	b.WriteString("Every configurable, non-deprecated provider argument of a kind's consumed\n")
	b.WriteString("resources must be matched to a spec field, mapped by recorded judgment, or\n")
	b.WriteString("excluded with a recorded reason -- and every spec field must reach provider\n")
	b.WriteString("surface. **Accounted** means both directions hold with zero unexplained\n")
	b.WriteString("gaps. **Proven** means live end-to-end runs passed on both IaC engines.\n\n")
	fmt.Fprintf(&b, "**%d of %d kinds are at total accounting; %d proven live.**\n\n", accounted, len(acc.Kinds), proven)
	b.WriteString("| Kind | Provider args | Matched | Mapped | Excluded | Open gaps | Accounted | Proven |\n")
	b.WriteString("|---|---|---|---|---|---|---|---|\n")
	for _, k := range acc.Kinds {
		if k.MissingModule {
			fmt.Fprintf(&b, "| %s | — | — | — | — | no Terraform module | ❌ | %s |\n", k.Kind, renderProof(proofs[k.Kind]))
			continue
		}
		gaps := len(k.UnaccountedArgs) + len(k.UncoveredSpecFields) + len(k.ManifestStale)
		accountedCell := "❌"
		if k.Accounted() {
			accountedCell = "✅"
		}
		fmt.Fprintf(&b, "| %s | %d | %d | %d | %d | %d | %s | %s |\n",
			k.Kind, k.TotalArgs, k.MatchedArgs, k.MappedArgs, k.ExcludedArgs, gaps, accountedCell, renderProof(proofs[k.Kind]))
	}
	b.WriteString("\n")

	// Breadth totals.
	b.WriteString("## Breadth: every GA resource, one disposition\n\n")
	fmt.Fprintf(&b, "All resources of `%s@%s` land in exactly one class:\n\n", acc.GASchema, acc.GASchemaVersion)
	b.WriteString("| Disposition | Resources | Meaning |\n|---|---|---|\n")
	total := 0
	for _, class := range dispositionOrder {
		count := acc.DispositionTotals[class.name]
		total += count
		fmt.Fprintf(&b, "| %s | %d | %s |\n", class.label, count, class.meaning)
	}
	if und := acc.DispositionTotals[""]; und > 0 {
		total += und
		fmt.Fprintf(&b, "| UNDISPOSITIONED | %d | awaiting recorded judgment -- carried loudly in the CI baseline |\n", und)
	}
	fmt.Fprintf(&b, "| **Total** | **%d** | |\n\n", total)

	// Enumerated dispositions -- the verifiable record.
	b.WriteString("## The enumerated record\n\n")
	b.WriteString("The full per-resource record, so the accounting above is verifiable\n")
	b.WriteString("rather than trusted.\n")
	for _, class := range dispositionOrder {
		var rows []ResourceDisposition
		for _, d := range acc.Dispositions {
			if d.Disposition == class.name {
				rows = append(rows, d)
			}
		}
		if len(rows) == 0 {
			continue
		}
		fmt.Fprintf(&b, "\n### %s (%d)\n\n", class.label, len(rows))
		fmt.Fprintf(&b, "| Resource | %s |\n|---|---|\n", class.detailHeader)
		for _, d := range rows {
			fmt.Fprintf(&b, "| `%s` | %s |\n", d.Resource, d.Detail)
		}
	}
	return b.String()
}

func renderProof(p E2EProof) string {
	switch {
	case p.Proven():
		return "✅ " + strings.Join(p.Engines, ", ")
	case len(p.Engines) > 0:
		return "partial: " + strings.Join(p.Engines, ", ")
	default:
		return "—"
	}
}

// dispositionOrder fixes the rendering order and the reader-facing meaning
// of each class. Order tells the coverage story: what exists, what is
// structurally covered, what is coming, and what was deliberately set aside.
var dispositionOrder = []struct {
	name         string
	label        string
	meaning      string
	detailHeader string
}{
	{DispositionModeled, "Modeled", "consumed by a kind's Terraform module today", "Consuming kinds"},
	{DispositionIamCovered, "IAM-covered", "per-resource IAM member/binding/policy triplets, covered by the owning kinds' additive `iam_members` fields", "Detail"},
	{DispositionComposed, "Composed", "capability covered through an existing kind's surface rather than a kind of its own", "Recorded reason"},
	{DispositionModelPlanned, "Planned", "judged to be covered by a planned kind or planned composition, not built yet", "Recorded reason"},
	{DispositionDeferred, "Deferred", "deliberately not offered, each with the recorded reason", "Recorded reason"},
	{DispositionExcludedDeprecated, "Excluded as deprecated", "deprecated or superseded provider surface", "Recorded reason"},
}
